@@ -0,0 +1,158 @@
+// contactStore.mjs
+
+import { deepClone } from './utils.js';
+
+export function createContactStore(filePath) {
+  let contacts = [];
+
+  async function loadContacts() {
+    try {
+      const data = await Deno.readTextFile(filePath);
+      contacts = JSON.parse(data);
+    } catch (error) {
+      if (error instanceof Deno.errors.NotFound) {
+        // File not found, do nothing
+      } else {
+        throw error;
+      }
+    }
+  }
+
+  async function saveContacts() {
+    try {
+      const tempFilePath = filePath + '.tmp';
+      await Deno.writeTextFile(tempFilePath, JSON.stringify(contacts, null, 2));
+      await Deno.rename(tempFilePath, filePath);
+    } catch (error) {
+      throw error;
+    }
+  }
+
+  async function list() {
+    await loadContacts();
+    return deepClone(contacts);
+  }
+
+  async function get(id) {
+    await loadContacts();
+    const contact = contacts.find(c => c.id === id);
+    return contact ? deepClone(contact) : undefined;
+  }
+
+  async function add(contact) {
+    await loadContacts();
+
+    // Validate contact
+    if (!contact || typeof contact !== 'object') {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    if (!contact.id || typeof contact.id !== 'string' || contact.id.trim() === '') {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    if (contact.name && typeof contact.name !== 'string' || contact.name.trim() === '') {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    if (contact.email && typeof contact.email !== 'string') {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    if (contact.phone && typeof contact.phone !== 'string') {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    if (contact.tags && !Array.isArray(contact.tags)) {
+      throw new Error('INVALID_CONTACT');
+    }
+
+    // Check for duplicate id
+    if (contacts.some(c => c.id === contact.id)) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    contacts.push(contact);
+    await saveContacts();
+    return deepClone(contact);
+  }
+
+  async function update(id, patch) {
+    await loadContacts();
+
+    const contact = contacts.find(c => c.id === id);
+    if (!contact) {
+      throw new Error('NOT_FOUND');
+    }
+
+    // Validate patch
+    if (!patch || typeof patch !== 'object') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.id) {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.name && typeof patch.name !== 'string' || patch.name.trim() === '') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.email && typeof patch.email !== 'string') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.phone && typeof patch.phone !== 'string') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.tags && !Array.isArray(patch.tags)) {
+      throw new Error('INVALID_PATCH');
+    }
+
+    // Apply patch
+    if (patch.name) {
+      contact.name = patch.name.trim();
+    }
+
+    if (patch.email) {
+      contact.email = patch.email.trim().toLowerCase();
+    }
+
+    if (patch.phone) {
+      contact.phone = patch.phone.trim();
+    }
+
+    if (patch.tags) {
+      contact.tags = patch.tags.map(tag => tag.trim());
+    }
+
+    await saveContacts();
+    return deepClone(contact);
+  }
+
+  async function remove(id) {
+    await loadContacts();
+
+    const index = contacts.findIndex(c => c.id === id);
+    if (index === -1) {
+      throw new Error('NOT_FOUND');
+    }
+
+    contacts.splice(index, 1);
+    await saveContacts();
+  }
+
+  return {
+    list,
+    get,
+    add,
+    update,
+    remove
+  };
+}
+
+// utils.js
+export function deepClone(obj) {
+  return JSON.parse(JSON.stringify(obj));
+}

